package com.customshop;import net.milkbowl.vault.economy.Economy;import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.configuration.ConfigurationSection;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.plugin.RegisteredServiceProvider;import org.bukkit.plugin.java.JavaPlugin;import java.util.*;public class CustomShopPlugin extends JavaPlugin implements Listener, CommandExecutor { private Economy eco; private final Map<Integer,String> shop=new HashMap<>(); public void onEnable(){saveDefaultConfig(); if(!setupEconomy()){getLogger().severe("Vault economy missing"); getServer().getPluginManager().disablePlugin(this); return;} getCommand("shop").setExecutor(this); Bukkit.getPluginManager().registerEvents(this,this);} private boolean setupEconomy(){RegisteredServiceProvider<Economy> rsp=getServer().getServicesManager().getRegistration(Economy.class); if(rsp==null)return false; eco=rsp.getProvider(); return eco!=null;} public boolean onCommand(CommandSender s, Command c,String l,String[] a){ if(!(s instanceof Player p)) return true; Inventory inv=Bukkit.createInventory(null,getConfig().getInt("size",27),ChatColor.translateAlternateColorCodes('&',getConfig().getString("shop-title"))); shop.clear(); ConfigurationSection sec=getConfig().getConfigurationSection("items"); for(String k:sec.getKeys(false)){ var cs=sec.getConfigurationSection(k); Material m=Material.valueOf(cs.getString("material")); ItemStack item=new ItemStack(m,cs.getInt("amount")); ItemMeta meta=item.getItemMeta(); meta.setDisplayName(ChatColor.translateAlternateColorCodes('&',cs.getString("name"))); meta.setLore(cs.getStringList("lore").stream().map(x->ChatColor.translateAlternateColorCodes('&',x)).toList()); item.setItemMeta(meta); int slot=cs.getInt("slot"); inv.setItem(slot,item); shop.put(slot,k);} p.openInventory(inv); return true;} @EventHandler public void click(InventoryClickEvent e){ if(!e.getView().getTitle().equals(ChatColor.translateAlternateColorCodes('&',getConfig().getString("shop-title")))) return; e.setCancelled(true); if(!(e.getWhoClicked() instanceof Player p)) return; String id=shop.get(e.getRawSlot()); if(id==null) return; var cs=getConfig().getConfigurationSection("items."+id); double price=cs.getDouble("price"); if(eco.getBalance(p)<price){msg(p,"nomoney"); return;} ItemStack give=new ItemStack(Material.valueOf(cs.getString("material")),cs.getInt("amount")); if(p.getInventory().firstEmpty()==-1){msg(p,"full"); return;} var r=eco.withdrawPlayer(p,price); if(!r.transactionSuccess()){msg(p,"error"); return;} p.getInventory().addItem(give); p.sendMessage(color(getConfig().getString("messages.bought").replace("%item%",cs.getString("name")).replace("%price%",String.valueOf((int)price)))); } private void msg(Player p,String path){p.sendMessage(color(getConfig().getString("messages."+path)));} private String color(String s){return ChatColor.translateAlternateColorCodes('&',s);} }
